from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(x for row in grid for x in row)
    base = {color for color, _ in counts.most_common(2)}

    special_rows = [
        r for r in range(h)
        if any(value not in base for value in grid[r])
    ]
    special_cols = [
        c for c in range(w)
        if any(grid[r][c] not in base for r in range(h))
    ]

    # The repeated color inside the lattice cells is the default output color.
    interior = [
        grid[r][c]
        for r in range(h) if r not in special_rows
        for c in range(w) if c not in special_cols
    ]
    default = Counter(interior).most_common(1)[0][0]

    result = []
    for r1, r2 in zip(special_rows, special_rows[1:]):
        row = []
        for c1, c2 in zip(special_cols, special_cols[1:]):
            corners = (grid[r1][c1], grid[r1][c2],
                       grid[r2][c1], grid[r2][c2])
            row.append(corners[0] if len(set(corners)) == 1 else default)
        result.append(row)
    return result
